import json
import re
import sys

status="invalid"; failureCode="400"; failureMessage="Input validation failed"; failureError="One or more lifecycle inputs are invalid."; failureResult="{}"
organizationName=sys.argv[1].strip(); deploymentName=sys.argv[2].strip(); mode=sys.argv[3].strip(); requiredConfirmation=sys.argv[4].strip().lower()=="true"
waitRequested=sys.argv[5].strip().lower()=="true"; timeoutText=sys.argv[6].strip(); requestedAction=sys.argv[7].strip(); placementConfirmation=sys.argv[8].strip().lower()=="true"
errors=[]; namePattern=re.compile(r"^[a-zA-Z0-9][a-zA-Z0-9\- _]{0,31}$")
if not organizationName: errors.append("Workload Organization must not be blank.")
if not namePattern.fullmatch(deploymentName): errors.append("Workload Deployment Name is invalid.")
if mode in {"prepare","deploy","undeploy"} and not requiredConfirmation: errors.append("The required confirmation input must be true.")
actionByMode={"prepare":"PrepareToDeploy","deploy":"Deploy","undeploy":"Undeploy"}
if mode=="manage":
    action=requestedAction
    if action not in {"Suspend","Resume","Retry","ReEvaluateQualifiers"}: errors.append("Action must be Suspend, Resume, Retry, or ReEvaluateQualifiers.")
    if action=="ReEvaluateQualifiers" and not placementConfirmation: errors.append("Confirm Placement Re-evaluation must be true for ReEvaluateQualifiers.")
else: action=actionByMode.get(mode,"")
try: waitTimeout=int(timeoutText)
except Exception: waitTimeout=0
if waitRequested and not (1<=waitTimeout<=600): errors.append("Wait Timeout Seconds must be 1 through 600 when waiting.")
if not waitRequested and not (0<=waitTimeout<=600): errors.append("Wait Timeout Seconds must be 0 through 600 when not waiting.")
escapedOrganizationName=organizationName.replace("'","''"); escapedDeploymentName=deploymentName.replace("'","''"); waitRequestedText="true" if waitRequested else "false"
if errors: failureError=" ".join(errors); failureResult=json.dumps({"error":failureMessage,"details":failureError},separators=(",",":"))
else: status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"

import json
import sys

status="invalid"; failureCode="422"; failureMessage="Lifecycle precondition failed"; failureError="The requested action is not valid for the current deployment state."; failureResult="{}"; requestBody=""
try:
    item=json.loads(sys.argv[1]); mode=sys.argv[2]; action=sys.argv[3]; currentStatus=str(item.get("Status","")).strip(); validation=item.get("ValidationInformation")
    allowed=False; reason=""
    if mode=="prepare":
        allowed=currentStatus=="Draft" and isinstance(validation,dict) and validation.get("State")=="Valid"; reason="PrepareToDeploy requires Draft with ValidationInformation.State Valid."
    elif mode=="deploy":
        allowed=currentStatus in {"ReadyToDeploy","ChangesScheduled"}; reason="Deploy requires ReadyToDeploy or ChangesScheduled."
    elif mode=="undeploy":
        allowed=currentStatus not in {"Draft","InProgress"}; reason="Undeploy requires a non-Draft state with no lifecycle action InProgress."
    elif mode=="manage":
        if action=="Suspend": allowed=currentStatus in {"ReadyToDeploy","Ok","ChangesScheduled"}; reason="Suspend is limited to ReadyToDeploy, Ok, or ChangesScheduled."
        elif action=="Resume": allowed=currentStatus=="Suspended"; reason="Resume requires Suspended."
        elif action=="Retry": allowed=currentStatus=="Failed"; reason="Retry requires Failed."
        elif action=="ReEvaluateQualifiers": allowed=currentStatus in {"Draft","ReadyToDeploy","Ok","Failed","ChangesScheduled"}; reason="ReEvaluateQualifiers is refused for Suspended and InProgress states."
    if not allowed:
        failureError=reason+" Current Status is "+currentStatus+"."
        failureResult=json.dumps({"error":failureMessage,"Action":action,"Status":currentStatus,"required":reason,"mutationSent":False},separators=(",",":"))
    else:
        requestBody=json.dumps({"ClassId":"workload.WorkloadDeployment","ObjectType":"workload.WorkloadDeployment","Action":action},separators=(",",":")); status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"
except Exception as exc:
    failureError="Lifecycle precondition evaluation failed closed: "+str(exc); failureResult=json.dumps({"error":failureMessage,"details":failureError,"mutationSent":False},separators=(",",":"))

import json
import sys
import time

status="invalid"; failureCode="500"; failureMessage="Polling delay failed"; failureError="The bounded polling delay could not complete."; failureResult="{}"
try:
    deadline=float(sys.argv[1]); initial=float(sys.argv[2]); interval=float(sys.argv[3]); attempt=int(sys.argv[4])
    if attempt<1 or attempt>5: raise ValueError("Poll attempt must be 1 through 5.")
    requested=initial if attempt==1 else interval; remaining=deadline-time.time()
    if remaining<=0:
        failureCode="408"; failureMessage="Lifecycle wait timed out"; failureError="The deadline was reached before poll attempt "+str(attempt)+"."; failureResult=json.dumps({"error":failureMessage,"requestAccepted":True,"timeout":True,"pollAttempt":attempt},separators=(",",":"))
    else:
        time.sleep(min(requested,remaining)); status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"
except Exception as exc:
    failureError="Polling delay helper failed: "+str(exc); failureResult=json.dumps({"error":failureMessage,"details":failureError,"requestAccepted":True},separators=(",",":"))

import datetime
import json
import sys

status="invalid"; failureCode="502"; failureMessage="Lifecycle poll response was invalid"; failureError="The polled deployment item could not be validated."; failureResult="{}"; pollState="invalid"; pollResult="{}"; observedStatus=""; acknowledged="false"
try:
    item=json.loads(sys.argv[1]); expectedMoid=sys.argv[2]; expectedName=sys.argv[3]; orgMoid=sys.argv[4]; action=sys.argv[5]; preModTime=sys.argv[6]; preStatus=sys.argv[7]; mode=sys.argv[8]
    if item.get("Moid")!=expectedMoid or item.get("Name")!=expectedName or item.get("ClassId")!="workload.WorkloadDeployment" or item.get("ObjectType")!="workload.WorkloadDeployment": raise ValueError("Polled deployment identity does not match.")
    org=item.get("Organization")
    if not isinstance(org,dict) or org.get("Moid")!=orgMoid or org.get("ObjectType")!="organization.Organization": raise ValueError("Polled Organization relationship does not match.")
    modTime=str(item.get("ModTime","")).strip(); datetime.datetime.fromisoformat(modTime.replace("Z","+00:00"))
    observedStatus=str(item.get("Status","")).strip(); lastAction=str(item.get("LastAction","None")).strip()
    allowedStatuses={"Draft","ReadyToDeploy","InProgress","Ok","Failed","ChangesScheduled","Suspended"}; allowedActions={"None","PrepareToDeploy","Deploy","Suspend","Retry","Resume","Undeploy","ReEvaluateQualifiers"}
    if observedStatus not in allowedStatuses or lastAction not in allowedActions: raise ValueError("Polled status or LastAction is outside the documented enum.")
    ack=(lastAction==action and modTime!=preModTime) or observedStatus!=preStatus; acknowledged="true" if ack else "false"
    successByMode={"prepare":{"ReadyToDeploy"},"deploy":{"Ok"},"undeploy":{"Draft"}}
    if mode=="manage": successStates={"Suspended"} if action=="Suspend" else {"Ok","ReadyToDeploy","ChangesScheduled"}
    else: successStates=successByMode.get(mode,set())
    if ack and observedStatus=="Failed": pollState="failure"
    elif ack and mode in {"deploy","manage"} and observedStatus=="ChangesScheduled": pollState="scheduled"
    elif ack and observedStatus in successStates: pollState="success"
    else: pollState="progress"
    pollResult=json.dumps({"Moid":expectedMoid,"Name":expectedName,"Action":action,"LastAction":lastAction,"Status":observedStatus,"acknowledged":ack,"ModTime":modTime,"InstanceStatusSummary":item.get("InstanceStatusSummary"),"InstanceConformanceSummary":item.get("InstanceConformanceSummary"),"preMutationModTime":preModTime,"raceDisclosure":"The deployment state was read before PATCH, but the request carried no version precondition; a concurrent same-item change can race the write."},separators=(",",":"),ensure_ascii=False,allow_nan=False)
    status="ready"; failureCode=failureMessage=failureError=""; failureResult="{}"
except Exception as exc:
    failureError="The lifecycle poll response failed validation: "+str(exc); failureResult=json.dumps({"error":failureMessage,"details":failureError,"requestAccepted":True,"preMutationModTime":preModTime,"raceDisclosure":"The lookup and PATCH were separate and may have raced a concurrent same-item change."},separators=(",",":"))
